using System.Collections;using UnityEngine;namespace FallenForest.World{public sealed class RuntimeQualityController:MonoBehaviour{[SerializeField]private int targetFrameRate=60;[SerializeField]private float highShadowDistance=58f,lowShadowDistance=36f,highLodBias=1.35f,lowLodBias=.92f,downgradeBelowFps=43f,upgradeAboveFps=54f,sampleWindow=4f;private bool reduced;private void Awake(){QualitySettings.vSyncCount=0;Application.targetFrameRate=targetFrameRate;QualitySettings.anisotropicFiltering=AnisotropicFiltering.ForceEnable;ApplyHigh();}private IEnumerator Start(){yield return new WaitForSecondsRealtime(8f);while(true){float elapsed=0;int frames=0;while(elapsed<sampleWindow){elapsed+=Time.unscaledDeltaTime;frames++;yield return null;}float fps=frames/Mathf.Max(.01f,elapsed);if(!reduced&&fps<downgradeBelowFps)ApplyLow();else if(reduced&&fps>upgradeAboveFps)ApplyHigh();}}private void ApplyHigh(){reduced=false;QualitySettings.shadowDistance=highShadowDistance;QualitySettings.lodBias=highLodBias;}private void ApplyLow(){reduced=true;QualitySettings.shadowDistance=lowShadowDistance;QualitySettings.lodBias=lowLodBias;}}}
